SELECT ns.id, ns.name, ns.slug, ns.location, ns.description, ns.logo_url as logoUrl, COUNT(na.id) as totalArticles FROM newspaper_sources ns LEFT JOIN newspaper_articles na ON ns.id = na.source_id AND na.is_active = true WHERE ns.is_active = true
AND ns.name ILIKE CONCAT('%', #{search}, '%')
GROUP BY ns.id ORDER BY ns.name LIMIT #{limit} OFFSET #{offset}

SELECT

FROM newspaper_articles na
LEFT JOIN newspaper_sources ns ON na.source_id = ns.id
WHERE na.is_active = true
AND EXISTS (
SELECT 1 FROM article_genres ag JOIN genres g ON ag.genre_id = g.id
WHERE ag.article_id = na.id AND g.slug = #{categorySlug}
)
AND na.publish_date >= #{criteria.dateFrom}
AND na.publish_date <= #{criteria.dateTo}
AND ns.name ILIKE CONCAT('%', #{criteria.source}, '%')
AND na.importance = #{criteria.importance}
ORDER BY

    na.publish_date
    na.view_count
    na.average_rating
    na.importance DESC, na.publish_date

ASC
DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM newspaper_articles na
LEFT JOIN newspaper_sources ns ON na.source_id = ns.id
WHERE na.is_active = true
AND EXISTS (
SELECT 1 FROM article_genres ag JOIN genres g ON ag.genre_id = g.id
WHERE ag.article_id = na.id AND g.slug = #{categorySlug}
)
AND na.publish_date >= #{criteria.dateFrom}
AND na.publish_date <= #{criteria.dateTo}
AND ns.name ILIKE CONCAT('%', #{criteria.source}, '%')
AND na.importance = #{criteria.importance}

SELECT COUNT(*) FROM newspaper_articles na
WHERE na.publish_date = #{date} AND na.is_active = true

    AND EXISTS (
    SELECT 1 FROM article_genres ag JOIN genres g ON ag.genre_id = g.id
    WHERE ag.article_id = na.id AND g.slug = #{category}
    )

SELECT,
ts_rank(na.search_vector, plainto_tsquery('indonesian', #{criteria.searchQuery})) as rank
FROM newspaper_articles na
LEFT JOIN newspaper_sources ns ON na.source_id = ns.id
WHERE na.search_vector @@ plainto_tsquery('indonesian', #{criteria.searchQuery})
AND na.is_active = true

    AND EXISTS (
    SELECT 1 FROM article_genres ag JOIN genres g ON ag.genre_id = g.id
    WHERE ag.article_id = na.id AND g.slug = #{criteria.category}
    )

AND na.publish_date >= #{criteria.dateFrom}
AND na.publish_date <= #{criteria.dateTo}
AND ns.name ILIKE CONCAT('%', #{criteria.source}, '%')
AND na.importance = #{criteria.importance}
ORDER BY rank DESC, na.publish_date DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM newspaper_articles na
LEFT JOIN newspaper_sources ns ON na.source_id = ns.id
WHERE na.search_vector @@ plainto_tsquery('indonesian', #{criteria.searchQuery})
AND na.is_active = true

    AND EXISTS (
    SELECT 1 FROM article_genres ag JOIN genres g ON ag.genre_id = g.id
    WHERE ag.article_id = na.id AND g.slug = #{criteria.category}
    )

AND na.publish_date >= #{criteria.dateFrom}
AND na.publish_date <= #{criteria.dateTo}
AND ns.name ILIKE CONCAT('%', #{criteria.source}, '%')
AND na.importance = #{criteria.importance}

SELECT COUNT(*) FROM newspaper_articles
WHERE EXTRACT(MONTH FROM publish_date) = #{month}
AND EXTRACT(DAY FROM publish_date) = #{day}
AND is_active = true

SELECT EXISTS(
SELECT 1 FROM article_views
WHERE viewer_hash = #{viewerHash} AND action_type::text = #{actionType}
)

mapper.update:
UPDATE newspaper_articles
SET is_active = false, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT EXISTS(
SELECT 1 FROM newspaper_articles
WHERE source_id = #{sourceId} AND slug = #{slug} AND id != #{excludeId}
)

SELECT a.* FROM authors a
JOIN article_authors aa ON a.id = aa.author_id
WHERE aa.article_id = #{articleId}

SELECT na.publish_date AS publishDate, COUNT(*) AS articleCount
FROM newspaper_articles na
WHERE na.source_id = #{sourceId} AND na.is_active = true
AND EXTRACT(YEAR FROM na.publish_date) = #{year}
AND EXTRACT(MONTH FROM na.publish_date) = #{month}
AND na.publish_date >= #{dateFrom}
AND na.publish_date <= #{dateTo}
GROUP BY na.publish_date
ORDER BY na.publish_date DESC

SELECT na.*
FROM newspaper_articles na
LEFT JOIN newspaper_sources ns ON na.source_id = ns.id
WHERE ns.slug = #{sourceSlug}
AND na.publish_date = #{date}
AND na.slug = #{articleSlug}
AND na.is_active = true
